  val stories = remember {
    listOf(
      QuranStory("آدم عليه السلام","الأنبياء","خلق الله آدم وعلّمه الأسماء، وأسجد له الملائكة، ثم وقع الابتلاء بالأكل من الشجرة، فتاب آدم إلى ربه وقبل الله توبته.","التوبة والرجوع إلى الله والحذر من وسوسة الشيطان.","البقرة: ٣٠–٣٩، الأعراف: ١١–٢٧، طه: ١١٥–١٢٣"),
      QuranStory("نوح عليه السلام","الأنبياء","دعا نوح قومه إلى التوحيد ليلًا ونهارًا، وصبر على إعراضهم، ثم أمره الله بصنع الفلك، فكانت النجاة للمؤمنين.","الصبر والثبات في الدعوة.","هود: ٢٥–٤٩، سورة نوح"),
      QuranStory("هود عليه السلام","الأنبياء","أرسل الله هودًا إلى عاد، فدعاهم إلى عبادة الله وترك الكبر، فكذبوه، فنجّى الله نبيه والذين آمنوا معه.","لا تغتر بالقوة؛ فهي لا تنفع مع الكفر والظلم.","الأعراف: ٦٥–٧٢، هود: ٥٠–٦٠"),
      QuranStory("صالح عليه السلام","الأنبياء","أرسل الله صالحًا إلى ثمود، وأيّده بالناقة آية، وأمرهم ألا يمسوها بسوء، لكن المعتدين عقروا الناقة فأخذتهم الرجفة.","احترام آيات الله وترك الفساد.","الأعراف: ٧٣–٧٩، هود: ٦١–٦٨"),
      QuranStory("إبراهيم عليه السلام","الأنبياء","حاجّ إبراهيم قومه في عبادة الأصنام، وأظهر عجزها، وابتلاه الله فصبر، ورفع قواعد البيت مع إسماعيل.","التوحيد والشجاعة في الحق والتوكل.","الأنبياء: ٥١–٧٠، البقرة: ١٢٤–١٢٩"),
      QuranStory("إسماعيل عليه السلام","الأنبياء","ذكر القرآن إسماعيل بالصدق والوفاء بالوعد، وشارك أباه إبراهيم في رفع قواعد الكعبة.","الوفاء والصبر والطاعة.","مريم: ٥٤–٥٥، البقرة: ١٢٥–١٢٩"),
      QuranStory("لوط عليه السلام","الأنبياء","دعا لوط قومه إلى ترك الفاحشة، فلما أصروا على الفساد نجّى الله لوطًا وأهله المؤمنين إلا امرأته.","العفة والابتعاد عن الفساد والاستجابة للنصح.","هود: ٧٧–٨٣، الحجر: ٥٧–٧٧"),
      QuranStory("يوسف عليه السلام","الأنبياء","رأى يوسف رؤيا، ثم مر بابتلاءات متتابعة، فصبر وحفظ نفسه، ثم مكّنه الله واجتمع بأهله.","العفة والصبر والعفو وحسن الظن بالله.","سورة يوسف: ٤–١٠١"),
      QuranStory("أيوب عليه السلام","الأنبياء","ابتلى الله أيوب، فصبر ولجأ إلى ربه بالدعاء، فكشف الله ضره وآتاه أهله ومثلهم معهم.","الصبر مع الدعاء وعدم اليأس من رحمة الله.","الأنبياء: ٨٣–٨٤، ص: ٤١–٤٤"),
      QuranStory("شعيب عليه السلام","الأنبياء","دعا شعيب أهل مدين إلى توحيد الله وإيفاء الكيل والميزان وترك بخس الناس حقوقهم، لكن المتكبرين كذبوه.","الأمانة والعدل في التعامل.","الأعراف: ٨٥–٩٣، هود: ٨٤–٩٥"),
      QuranStory("موسى عليه السلام","الأنبياء","أوحى الله إلى أم موسى أن تلقيه في اليم، فرده إليها، ثم أرسله إلى فرعون وأيده بالآيات، ونجّى بني إسرائيل.","الثقة بوعد الله والثبات أمام الظلم.","القصص: ٧–٣٥، طه: ٩–٩٨، الشعراء: ٥٢–٦٨"),
      QuranStory("هارون عليه السلام","الأنبياء","كان هارون نبيًا ووزيرًا لأخيه موسى، يعينه في تبليغ الرسالة، وذكّر قومه حين فتنوا بالعجل.","التعاون على الخير والرفق في النصح.","طه: ٢٩–٩٤، الأعراف: ١٤٢–١٥١"),
      QuranStory("داود عليه السلام","الأنبياء","آتَى الله داود الملك والحكمة، وسخّر معه الجبال والطير يسبحن، وعلّمه الفصل بين الناس.","العدل وشكر النعمة وكثرة الذكر.","ص: ١٧–٢٦، سبأ: ١٠–١١"),
      QuranStory("سليمان عليه السلام","الأنبياء","آتَى الله سليمان ملكًا عظيمًا وعلّمه منطق الطير، وتفقد الهدهد، ودعا ملكة سبأ إلى عبادة الله.","الشكر والتواضع واستعمال النعمة في الخير.","النمل: ١٥–٤٤، ص: ٣٠–٤٠"),
      QuranStory("يونس عليه السلام","الأنبياء","ذهب يونس مغاضبًا، فكان في الظلمات ودعا ربه بكلمات التوحيد والتنزيه، فاستجاب الله له ونجّاه.","الإنابة إلى الله والإكثار من الدعاء.","الأنبياء: ٨٧–٨٨، الصافات: ١٣٩–١٤٨"),
      QuranStory("زكريا عليه السلام","الأنبياء","دعا زكريا ربه سرًا أن يهب له ولدًا، فبشره الله بيحيى على كبر سنه.","حسن الدعاء والرجاء وعدم القنوط.","آل عمران: ٣٧–٤١، مريم: ٢–١١"),
      QuranStory("يحيى عليه السلام","الأنبياء","آتَى الله يحيى الحكم صبيًا، وجعله بارًا بوالديه، وأثنى عليه بالزكاة والتقوى والسلام.","البر بالوالدين والعفة والتقوى.","مريم: ١٢–١٥، آل عمران: ٣٩"),
      QuranStory("عيسى عليه السلام","الأنبياء","ولد عيسى بآية من الله، وتكلم في المهد بإذن الله، وأيده الله بالبينات، ودعا بني إسرائيل إلى عبادة الله.","الإيمان بقدرة الله وعبادته وحده.","آل عمران: ٤٥–٥١، مريم: ١٦–٣٦"),
      QuranStory("مريم عليها السلام","نساء صالحات","اصطفى الله مريم وطهرها، ورزقها من فضله، وبشرها بعيسى عليه السلام، فكانت آية للعالمين.","العبادة والعفة والثقة بالله.","آل عمران: ٣٥–٤٧، مريم: ١٦–٣٦"),
      QuranStory("أصحاب الكهف","قصص القرآن","كانوا فتية آمنوا بربهم وفروا بدينهم، فآواهم الله إلى الكهف وأنامهم سنين طويلة ثم بعثهم.","الثبات على الإيمان وصحبة أهل الخير.","الكهف: ٩–٢٦"),
      QuranStory("ذو القرنين","قصص القرآن","مكّن الله ذا القرنين في الأرض، فسار فيها بالعدل، وأعان قومًا على بناء ردم يحجز يأجوج ومأجوج.","القوة أمانة، والنجاح يكون بالعدل ونسبة الفضل لله.","الكهف: ٨٣–٩٨"),
      QuranStory("طالوت وجالوت","قصص القرآن","اختار الله طالوت ملكًا لبني إسرائيل، فاختبر جنوده بالنهر، وثبتت فئة مؤمنة فواجهت جالوت وانتصروا بإذن الله.","الثبات وقلة العدد لا تمنع النصر بإذن الله.","البقرة: ٢٤٦–٢٥١"),
      QuranStory("قارون","قصص القرآن","آتَى الله قارون كنوزًا عظيمة، فبغى على قومه ونسب الفضل إلى نفسه، فخسف الله به وبداره الأرض.","ترك الكبر وعدم الاغترار بالمال.","القصص: ٧٦–٨٢"),
      QuranStory("أصحاب الجنة","قصص القرآن","عزم أصحاب بستان على منع المساكين من ثمره، فذهبوا إليه فوجدوه قد صار كالصريم، فعرفوا خطأهم.","شكر النعمة وإعطاء المحتاج حقه.","القلم: ١٧–٣٣"),
      QuranStory("أصحاب الأخدود","قصص القرآن","ذكر القرآن قومًا عذبوا المؤمنين بسبب إيمانهم، وتوعد الظالمين الذين فتنوا المؤمنين ولم يتوبوا.","الثبات على الإيمان والتحذير من ظلم الناس.","البروج: ٤–١٠"),
      QuranStory("أصحاب الفيل","قصص القرآن","ذكر الله كيف رد كيد أصحاب الفيل الذين قصدوا البيت الحرام، وأرسل عليهم طيرًا أبابيل.","قدرة الله فوق كل قوة.","سورة الفيل كاملة"),
      QuranStory("سبأ وملكة سبأ","قصص القرآن","أخبر الهدهد سليمان عن قوم تملكهم امرأة يعبدون الشمس، فأرسل إليها كتابًا يدعوها إلى الله، فكان في القصة تدبر وحوار.","التثبت من الأخبار والحكمة في الدعوة والشكر.","النمل: ٢٠–٤٤"),
      QuranStory("غزوة بدر الكبرى", "السيرة النبوية • أحداث تاريخية", "قصة يوم الفرقان وما فيه من ثبات المؤمنين ودعائهم وتوكلهم.", "الثبات والتوكل والشورى والتواضع.", "الأنفال: ٥–١٩، ٤١–٤٤؛ آل عمران: ١٢٣–١٢٧", listOf("الصفحة الأولى: الطريق إلى بدر\n\nكانت المدينة المنورة في السنوات الأولى بعد الهجرة مجتمعًا جديدًا يتعلم تنظيم حياته على أساس الإيمان والتعاون. وكان المسلمون قد تركوا مكة بعد ما لاقوه من أذى، وترك كثير منهم بيوتهم وأموالهم، ثم بدأوا في المدينة حياة جديدة. لم تكن الظروف سهلة؛ فقد واجه المجتمع تحديات اقتصادية واجتماعية، وكان المسلمون حريصين على حماية جماعتهم والوفاء بالعهود.\n\nفي السنة الثانية للهجرة وقع حدث بدر، وهو من أشهر أحداث السيرة النبوية. وتذكر كتب السيرة أن المسلمين خرجوا في سياق التوتر القائم مع قريش وما سبق ذلك من مصادرة أموال المهاجرين واستمرار العداء. ثم تطورت الأحداث حتى أصبح اللقاء عند بدر. لم يكن المسلمون يتعاملون مع الأمر على أنه مجال للغرور أو التفاخر، بل كان النبي صلى الله عليه وسلم يرجع إلى الله بالدعاء، ويأخذ بمبدأ الشورى، ويستمع إلى أصحابه.\n\nومن المهم أن نفهم زمن القصة وسياقها، وألا نحول أحداث التاريخ إلى دعوة للعنف في حياتنا اليوم. فالسيرة تدرس لفهم مواقف النبي صلى الله عليه وسلم، وصبر أصحابه، وكيف واجه المجتمع المسلم ظروفًا صعبة في ذلك العصر. كما نتعلم أن الأخبار التاريخية تُراجع في مصادرها، وأن الروايات قد تختلف في بعض الجزئيات، لذلك نرجع إلى القرآن الكريم وكتب السيرة المعروفة.\n\nوتُظهر آيات سورة الأنفال جوانب من الحدث، وتلفت النظر إلى أن النصر ليس ملكًا للبشر يتصرفون فيه كما يشاؤون، بل هو من عند الله، وأن على المؤمن أن يتواضع ولا ينسب الفضل إلى نفسه.", "الصفحة الثانية: الشورى والثبات والدعاء\n\nتذكر كتب السيرة أن النبي صلى الله عليه وسلم شاور أصحابه قبل اللقاء، فكان في ذلك درس عظيم في القيادة. فالقائد الحكيم لا يستغني عن رأي من حوله، ولا يجعل مكانته سببًا لرفض النصيحة. وقد عبّر الصحابة عن استعدادهم للوقوف مع رسول الله صلى الله عليه وسلم، وظهر معنى الأخوة في اجتماعهم على موقف واحد. كانت الشورى وسيلة لفهم الظروف وتوحيد الصف.\n\nومن المواقف التي تبرز في روايات بدر دعاء النبي صلى الله عليه وسلم وتضرعه إلى الله. وهذا يعلّم المسلم أن يأخذ بالأسباب المشروعة، ثم لا يتعلق بقوته وحدها، بل يسأل الله العون والهداية. فالتوكل الصحيح لا يعني ترك العمل، كما أن العمل لا يعني نسيان فضل الله. يجمع المؤمن بين بذل الجهد والتواضع والافتقار إلى ربه.\n\nوتعرض سورة الأنفال مشاهد من ذلك اليوم، وتذكر تثبيت الله للمؤمنين، كما توجههم إلى طاعة الله ورسوله وعدم التنازع. ومن هنا نفهم أن قيمة الحدث لا تختصر في نتيجة تاريخية، بل تشمل التربية التي صاحبتها: الصبر عند الخوف، والصدق عند الشدة، وضبط النفس، والالتزام بما أمر الله به.\n\nكما ينبغي ألا نضيف حوارات أو تفاصيل لا تثبت في المصادر ثم ننسبها إلى النبي صلى الله عليه وسلم أو الصحابة. فمحبة السيرة تكون بالأمانة في نقلها، لا بالمبالغة. وإذا اختلفت الروايات في تفصيل، فمن الأفضل ذكر وجود الاختلاف بدل تقديم أمر غير محقق على أنه يقين.", "الصفحة الثالثة: النتائج والدروس\n\nكان لحدث بدر أثر كبير في المجتمع المسلم وفي علاقته بقريش، وأصبح يومًا فارقًا في الذاكرة الإسلامية. وقد سمّى القرآن يومه يوم الفرقان، وارتبط ذكره بالتذكير بنعمة الله وتأييده. لكن المسلم لا يقرأ النصر ليغتر أو يتكبر، بل ليزداد شكرًا وتواضعًا، وليعرف أن القوة والعدد والمال لا تمنح الإنسان حق ظلم الآخرين.\n\nومن الدروس المهمة أن الشورى تقوي الجماعة؛ فالإنسان مهما كان صاحب خبرة يحتاج إلى نصيحة صادقة. ومنها أن الثبات لا يعني القسوة، وأن الشجاعة الحقيقية تقترن بضبط النفس والالتزام بالعدل. ومنها أن الدعاء ليس بديلًا عن المسؤولية، بل يرافقها ويهذب نية الإنسان. ومنها كذلك أن التاريخ لا يروى بالأهواء، بل بالأمانة والتحقق من الأخبار.\n\nفي حياتنا اليومية لا يجوز أن يتخذ أحد قصة بدر ذريعة لإيذاء الناس أو الاعتداء عليهم. موضع الاستفادة هو فهم السيرة في سياقها التاريخي، والاقتداء بما فيها من إيمان وصبر وشورى، مع الالتزام بأحكام الدين والأنظمة التي تحفظ الأرواح والحقوق في زماننا.\n\nخلاصة القصة أن بدرًا ليست مجرد اسم معركة؛ إنها صفحة من تاريخ النبوة تعلمنا أن المواقف العظيمة لا تنفصل عن الأخلاق. وبعد القراءة ارجع إلى سورة الأنفال واقرأ الآيات المشار إليها مع تفسير موثوق، ثم اكتب ثلاثة دروس عملية يمكن تطبيقها في المدرسة والبيت والتعامل مع الآخرين.")),
      QuranStory("غزوة أُحد", "السيرة النبوية • أحداث تاريخية", "قصة أُحد وما وقع فيها من ابتلاء، وما تعلمه المسلمون من الطاعة والصبر ومراجعة النفس.", "الانضباط والطاعة والصبر والتوبة.", "آل عمران: ١٢١–١٧٥", listOf("الصفحة الأولى: ما قبل أُحد\n\nبعد بدر دخل المسلمون مرحلة جديدة من تاريخهم، لكن التحديات لم تنته. كانت قريش تحمل آثار الهزيمة، واستمرت حالة التوتر بين مكة والمدينة. وفي السنة الثالثة للهجرة وقع حدث أُحد قرب المدينة المنورة. وتناولت سورة آل عمران جانبًا مهمًا من هذه الوقائع، فلم تذكر الأحداث لمجرد تسجيل التاريخ، بل ربطتها بتربية المؤمنين وتصحيح أخطائهم وتقوية قلوبهم.\n\nخرج النبي صلى الله عليه وسلم مع أصحابه في ذلك الظرف، وكان المسلمون يتشاورون ويتخذون ما يرونه مناسبًا لحماية المدينة. وتذكر كتب السيرة أن الرأي استقر على الخروج إلى أُحد. ومن المهم أن نقرأ هذه الأخبار باعتبارها جزءًا من سياق تاريخي محدد، لا باعتبارها تعليمات لصراعات في واقعنا المعاصر. فالمقصود فهم السيرة واستخلاص الأخلاق والمعاني الإيمانية.\n\nفي بداية الأحداث ظهرت مواقف من الشجاعة والثبات، وكان الصحابة رضي الله عنهم يحرصون على نصرة النبي صلى الله عليه وسلم. لكن القصة لم تكن سهلة، فقد وقع ابتلاء شديد، وتغيرت مجريات الموقف بعد مخالفة بعض الرماة للتوجيه الذي أُمروا بالالتزام به. وتشرح كتب التفسير أن هذه الحادثة صارت درسًا واضحًا في أهمية الطاعة والانضباط وعدم الاستعجال وراء المكاسب العاجلة.\n\nومن الإنصاف ألا نختصر أُحدًا في لحظة واحدة، أو نحكم على أشخاص دون فهم ما ورد في القرآن والسيرة. فقد كانت مرحلة تربية عظيمة، وفيها نزلت آيات تبين أسباب ما حدث وتدعو إلى الصبر والعفو والثبات.", "الصفحة الثانية: الابتلاء ومراجعة النفس\n\nتوضح آيات سورة آل عمران أن الابتلاء يكشف ما في النفوس ويعلم المؤمنين حقائق مهمة. فقد يمر الإنسان بلحظة يظن فيها أن الأمور تسير كما يريد، ثم يواجه ظرفًا صعبًا يجعله يعيد النظر في قراراته. وهذا لا يعني أن اليأس هو الطريق، بل يعني أن المؤمن يتعلم من الخطأ، ويعود إلى الصواب، ويستعين بالله.\n\nومن أبرز الدروس التي تذكرها قصة أُحد أن مخالفة التوجيه قد تؤثر في الجماعة كلها. فالعمل الجماعي يحتاج إلى التزام واتفاق، ولا يصح أن ينشغل كل شخص بمصلحته الخاصة وينسى المسؤولية المشتركة. ويمكن تطبيق هذا المعنى في المدرسة والبيت: عندما نتفق على نظام واضح، فإن احترامه يحمي الجميع ويمنع الفوضى.\n\nوتعلمنا أُحد كذلك أن الشجاعة ليست اندفاعًا بلا تفكير، وأن الحماس وحده لا يكفي. يحتاج الإنسان إلى الصبر والحكمة وسماع النصيحة. وإذا أخطأ فلا يجعل الخطأ نهاية الطريق، بل يعترف به ويتعلم منه ويصلح ما يستطيع إصلاحه. وهذا من معاني التوبة ومحاسبة النفس التي تتكرر في القرآن الكريم.\n\nوفي السورة توجيه إلى عدم الوهن والحزن، وإلى أن الأيام تتداول بين الناس، وأن المؤمن لا يقيس الحق بمجرد ما يراه من مكسب عاجل أو خسارة مؤقتة. وقد يكون في التجربة المؤلمة تعليم ورحمة، إذا قابلها الإنسان بالصبر والتوبة والعمل الصالح.", "الصفحة الثالثة: دروس أُحد في حياتنا\n\nأول درس عملي من أُحد هو أن الالتزام بالتوجيهات الصحيحة يحفظ الحقوق ويقلل الضرر. فالطالب الذي يتفق مع زملائه على خطة للمذاكرة ثم يترك مسؤوليته قد يربك المجموعة. وأفراد الأسرة الذين يتعاونون على أمر ثم يتجاهل أحدهم الاتفاق يسببون مشكلات يمكن تجنبها. هكذا نفهم أن الانضباط خلق يومي، وليس أمرًا يخص الأحداث الكبرى وحدها.\n\nوالدرس الثاني هو مراجعة النفس. قد يخطئ الإنسان في كلمة أو قرار أو تصرف، لكن الشجاعة الأخلاقية أن يعترف بالخطأ ويعتذر ويصلح أثره. لا ينبغي أن يحول الإنسان الخطأ إلى عناد، ولا أن يحمّل الآخرين كل المسؤولية. وتعلمنا آيات أُحد أن المؤمنين يتعلمون من التجربة، ويستغفرون، ويواصلون طريق الخير.\n\nوالدرس الثالث هو الرحمة عند الشدة. فقد وجه القرآن إلى العفو والاستغفار والشورى، وهي معانٍ عظيمة تظهر أن القيادة النبوية كانت تربية للقلوب. ومن يقرأ السيرة ينبغي أن يزداد حلمًا وعدلًا ورحمة، لا أن يبحث عن الخصومة أو الانتقام.\n\nفي نهاية القراءة، ارجع إلى الآيات من سورة آل عمران، واقرأ تفسيرًا موثوقًا لها. اكتب في دفتر مُتقن: ما التوجيه الذي ينبغي أن ألتزم به؟ ما الخطأ الذي أحتاج إلى مراجعته؟ وكيف أكون أكثر تعاونًا ورحمة؟ بهذه الطريقة تتحول القصة من معلومات محفوظة إلى أخلاق نافعة.")),
      QuranStory("غزوة الخندق والأحزاب", "السيرة النبوية • أحداث تاريخية", "قصة اجتماع الأحزاب حول المدينة، وثبات المسلمين في ظرف صعب، ثم انكشاف الأزمة وما فيها من دروس.", "التعاون والصبر وحسن الظن بالله والتثبت من الأخبار.", "الأحزاب: ٩–٢٧", listOf("الصفحة الأولى: المدينة في ظرف شديد\n\nفي السنة الخامسة للهجرة تقريبًا واجه المسلمون في المدينة حدثًا عظيمًا عُرف بغزوة الخندق أو الأحزاب. وقد سميت بالأحزاب لاجتماع جماعات مختلفة في موقف واحد ضد المدينة. وكانت المدينة مجتمعًا يحتاج إلى حماية واستقرار، وقد جاءت الأزمة في وقت صعب زادت فيه المخاوف والمسؤوليات.\n\nتتناول سورة الأحزاب هذه المرحلة، وتذكر كيف أحاطت الظروف الصعبة بالمؤمنين، وكيف ظهرت مواقف الناس على اختلافها. لم يكن الأمر مجرد حدث تاريخي؛ بل كان اختبارًا للإيمان والثقة بالله والتعاون بين أفراد المجتمع. وقد سجل القرآن مشاعر الخوف والقلق، ثم ذكر تثبيت الله للمؤمنين وانكشاف الشدة.\n\nومن أشهر ما تذكره كتب السيرة في هذه القصة فكرة حفر الخندق حول المدينة، وهي من الوقائع التي ارتبطت بالتشاور والاستفادة من الخبرات. ويظهر هنا معنى مهم: المجتمعات تتجاوز الأزمات عندما يتعاون أهلها، ويستمعون إلى الرأي النافع، ويتقاسمون المسؤوليات. وهدفنا من عرض هذه الواقعة هو فهم السيرة وأخلاقها، لا شرح أساليب القتال.\n\nكان النبي صلى الله عليه وسلم حاضرًا مع أصحابه في تحمل المشقة، ولم يكن يطلب منهم ما يعفي نفسه منه. وهذا من معاني القدوة؛ فالقائد الصادق يشارك الناس المسؤولية، ويواسيهم، ويثبتهم بالكلمة والعمل. كما أن الصحابة تعاونوا في ظرفهم، وكان كل منهم يؤدي ما يستطيع من واجب.", "الصفحة الثانية: الصبر والثقة بالله\n\nتصف آيات سورة الأحزاب شدة الموقف، وتبين أن المؤمنين تعرضوا لاختبار عظيم. ومن المعاني التي نتأملها أن الإيمان لا يعني أن الإنسان لا يشعر بالخوف أو التعب؛ فالإنسان بطبيعته يمر بمشاعر مختلفة، لكن المهم كيف يتعامل معها. المؤمن يلجأ إلى الله، ويأخذ بالأسباب المشروعة، ولا يسمح للخوف أن يدفعه إلى الظلم أو نشر الأذى.\n\nوتبرز القصة أهمية الكلمة الصادقة في وقت الأزمات. فقد يحتاج الناس إلى من يطمئنهم بالمعلومة الصحيحة، لا إلى من يضخم الأخبار أو ينشر ما لا يعرف. وهذا درس قريب من حياتنا اليوم؛ فعندما تنتشر رسالة مخيفة في مجموعات الهاتف، لا ينبغي إعادة إرسالها قبل التحقق من مصدرها. وقد تكون الشائعة سببًا في قلق الناس وإيذائهم.\n\nكما يظهر في القصة أثر التعاون. فالمجتمع القوي ليس الذي يعتمد على شخص واحد، بل الذي يعرف أفراده مسؤولياتهم ويتعاونون في حدود قدرتهم. في المدرسة، يتعاون الطلاب على التعلم واحترام النظام. وفي البيت، يتقاسم أفراد الأسرة الأعمال. وفي الحي، يساعد الناس بعضهم في الأمور النافعة ويحافظون على السلامة.\n\nوتعلمنا سورة الأحزاب أن الفرج من عند الله، وأن على المؤمن أن يحسن الظن بربه. لكن حسن الظن لا يعني ترك العمل، بل يعني الجمع بين الاستعداد الحكيم والدعاء والصبر.", "الصفحة الثالثة: انكشاف الأزمة والدروس الباقية\n\nتذكر آيات سورة الأحزاب أن الله رد الذين كفروا بغيظهم، وكفى المؤمنين القتال، وكان الله قويًا عزيزًا. وتختم القصة بمعنى واضح: أن تدبير الأمور بيد الله، وأن الإنسان مهما بذل من جهد يبقى محتاجًا إلى رحمة ربه وتوفيقه. وقد بقيت ذكرى الخندق في السيرة مثالًا على التعاون والصبر في ظرف بالغ الصعوبة.\n\nومن أهم ما نتعلمه أن الشورى ليست ضعفًا؛ بل هي طريق للاستفادة من عقول متعددة. وقد تأتي فكرة نافعة من شخص لا يتوقعه الآخرون، لذلك ينبغي احترام الرأي الجيد والنظر إلى مضمونه لا إلى مكانة صاحبه فقط. كما أن توزيع المسؤوليات يجعل العمل أيسر، ويمنع أن يتحمل شخص واحد كل العبء.\n\nونتعلم كذلك أن الأزمات تحتاج إلى معلومات موثوقة. لا ننشر خبرًا لمجرد أنه مثير، ولا نتهم الناس دون دليل، ولا نزيد خوف الآخرين بكلام غير مؤكد. هذه أخلاق إسلامية مهمة في زمن وسائل التواصل، حيث تنتقل الأخبار بسرعة وقد يصعب تصحيحها بعد انتشارها.\n\nهذه القصة قراءة لمرحلة من السيرة النبوية في سياقها التاريخي. المسلم اليوم يقتدي بالنبي صلى الله عليه وسلم في الصدق والرحمة والوفاء والصبر وحفظ الحقوق. بعد الانتهاء دوّن خبرًا تتحقق منه قبل نشره، ومسؤولية تتعاون فيها مع غيرك، ودعاءً تلتزم به وقت الشدة."))
    ) + additionalStorySeeds().map { seed ->
      val group = when {
        seed.source.contains("صحيح") || seed.source.contains("سنن") || seed.source.contains("مسند") || seed.source.contains("كتب السيرة") || seed.source.contains("التراجم") -> "السيرة والحديث"
        seed.title.startsWith("الذي") || seed.title.startsWith("الذين") -> "قيم وآداب"
        else -> "قصص القرآن"
      }
      QuranStory(seed.title, group, seed.summary, seed.lesson, seed.source)
    }
  }
  var query by remember { mutableStateOf("") }
  var expanded by remember { mutableIntStateOf(-1) }
  var pageIndex by remember { mutableIntStateOf(0) }
  var selectedGroup by remember { mutableStateOf("الكل") }
  var onlyFavorites by remember { mutableStateOf(false) }
  var refresh by remember { mutableIntStateOf(0) }
  val groups = remember(stories) { listOf("الكل") + stories.map { it.group }.distinct() }
  val filtered = remember(query, selectedGroup, onlyFavorites, refresh) {
    stories.withIndex().filter {
      val matchesQuery = it.value.title.contains(query.trim(), true) || it.value.group.contains(query.trim(), true) || it.value.summary.contains(query.trim(), true)
      val matchesGroup = selectedGroup == "الكل" || it.value.group == selectedGroup
      val matchesFavorite = !onlyFavorites || prefs.toolFlag("story_fav_${it.index}")
      matchesQuery && matchesGroup && matchesFavorite
    }
  }
  val colors = MaterialTheme.colorScheme
  Column(Modifier.fillMaxSize().background(colors.background).safeDrawingPadding()) {
    Card(Modifier.fillMaxWidth().padding(horizontal = 13.dp, vertical = 9.dp), shape = RoundedCornerShape(26.dp), colors = CardDefaults.cardColors(containerColor = colors.primary)) {
      Column(Modifier.fillMaxWidth().padding(16.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
        Row(verticalAlignment = Alignment.CenterVertically) {
          TextButton(onClick = onBack, colors = ButtonDefaults.textButtonColors(contentColor = colors.onPrimary)) { Text("رجوع") }
          Spacer(Modifier.weight(1f))
          Text("مكتبة مُتقن", color = colors.onPrimary.copy(alpha = .85f), fontSize = 11.sp)
        }
        Row(verticalAlignment = Alignment.CenterVertically, horizontalArrangement = Arrangement.spacedBy(12.dp)) {
          Box(Modifier.size(52.dp).background(colors.onPrimary.copy(alpha = .14f), RoundedCornerShape(17.dp)), contentAlignment = Alignment.Center) { Text("📚", fontSize = 27.sp) }
          Column {
            Text("مكتبة القصص والمواقف", fontSize = 24.sp, fontWeight = FontWeight.Black, color = colors.onPrimary)
            Text("${stories.size} قصة وموقف وعبرة • مع مواضع المصادر", fontSize = 11.sp, color = colors.onPrimary.copy(alpha = .88f))
          }
        }
      }
    }
    Card(Modifier.fillMaxWidth().padding(horizontal = 14.dp), shape = RoundedCornerShape(20.dp), colors = CardDefaults.cardColors(containerColor = colors.surfaceVariant)) {
      Column(Modifier.padding(15.dp)) {
        Text("اقرأ القصة من مصدرها", fontWeight = FontWeight.Bold, color = colors.onPrimaryContainer)
        Text("كل ملخص مرتبط بمواضع الآيات لتعود إلى القرآن وتتدبر السياق بنفسك.", fontSize = 11.sp, color = colors.onPrimaryContainer)
      }
    }
    OutlinedTextField(value = query, onValueChange = { query = it }, modifier = Modifier.fillMaxWidth().padding(horizontal = 14.dp, vertical = 10.dp), singleLine = true, shape = RoundedCornerShape(15.dp), label = { Text("ابحث باسم القصة أو القسم") })
    Row(Modifier.fillMaxWidth().padding(horizontal=14.dp),horizontalArrangement=Arrangement.spacedBy(8.dp),verticalAlignment=Alignment.CenterVertically) {
      FilterChip(selected=!onlyFavorites,onClick={onlyFavorites=false},label={Text("الكل")})
      FilterChip(selected=onlyFavorites,onClick={onlyFavorites=true},label={Text("المفضلة")})
      Text("${filtered.size} نتيجة",fontSize=11.sp,color=colors.onSurfaceVariant)
    }
    androidx.compose.foundation.lazy.LazyRow(
      contentPadding=PaddingValues(horizontal=14.dp),
      horizontalArrangement=Arrangement.spacedBy(7.dp)
    ) {
      items(groups) { group ->
        FilterChip(selected=selectedGroup==group,onClick={selectedGroup=group},label={Text(group,fontSize=10.sp)})
      }
    }
    LazyColumn(contentPadding = PaddingValues(horizontal = 14.dp, vertical = 4.dp), verticalArrangement = Arrangement.spacedBy(9.dp)) {
      items(filtered, key = { it.index }) { indexed ->
        val i = indexed.index
        val story = indexed.value
        Card(Modifier.fillMaxWidth().clickable { expanded = if (expanded == i) -1 else i; pageIndex = 0 }, shape = RoundedCornerShape(22.dp), colors = CardDefaults.cardColors(containerColor = colors.surface), elevation = CardDefaults.cardElevation(defaultElevation = 2.dp)) {
          Column(Modifier.padding(15.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
            Row(verticalAlignment = Alignment.CenterVertically) {
              Column(Modifier.weight(1f)) { Text(story.title, fontSize = 16.sp, fontWeight = FontWeight.Bold, color = colors.primary); Text(story.group, fontSize = 10.sp, color = colors.onSurfaceVariant) }
              Row(verticalAlignment=Alignment.CenterVertically) {
                TextButton(onClick={
                  prefs.setToolFlag("story_fav_${i}",!prefs.toolFlag("story_fav_${i}"))
                  refresh++
                }) { Text(if(prefs.toolFlag("story_fav_${i}")) "★" else "☆",fontSize=21.sp,color=colors.secondary) }
                Text(if (expanded == i) "−" else "+", fontSize = 23.sp, color = colors.secondary)
              }
            }
            if (expanded == i) {
              HorizontalDivider()
              Text(story.summary, fontSize = 13.sp, lineHeight = 22.sp)
              if (story.pages.isNotEmpty()) {
                Card(colors = CardDefaults.cardColors(containerColor = colors.primaryContainer), shape = RoundedCornerShape(14.dp)) {
                  Column(Modifier.fillMaxWidth().padding(12.dp), verticalArrangement = Arrangement.spacedBy(8.dp)) {
                    Text("قصة طويلة • الصفحة ${pageIndex + 1} من ${story.pages.size}", fontWeight = FontWeight.Bold, color = colors.onPrimaryContainer)
                    LinearProgressIndicator(progress = { (pageIndex + 1).toFloat() / story.pages.size }, modifier = Modifier.fillMaxWidth())
                    Text(story.pages[pageIndex], fontSize = 14.sp, lineHeight = 25.sp, color = colors.onPrimaryContainer)
                    Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween) {
                      OutlinedButton(onClick = { pageIndex = (pageIndex - 1).coerceAtLeast(0) }, enabled = pageIndex > 0) { Text("السابقة") }
                      Button(onClick = { pageIndex = (pageIndex + 1).coerceAtMost(story.pages.lastIndex) }, enabled = pageIndex < story.pages.lastIndex) { Text(if (pageIndex == story.pages.lastIndex) "اكتملت القصة" else "الصفحة التالية") }
                    }
                  }
                }
              }
              Text("🌱 العبرة", fontWeight = FontWeight.Bold, color = colors.primary, fontSize = 12.sp)
              Text(story.lesson, fontSize = 12.sp, lineHeight = 20.sp)
              Text("مواضع القصة في القرآن", fontWeight = FontWeight.Bold, fontSize = 11.sp)
              Text(story.source, fontSize = 11.sp, color = colors.secondary)
            } else Text("اضغط لعرض الملخص والعبرة والآيات", fontSize = 10.sp, color = colors.onSurfaceVariant)
          }
        }
      }
    }
    Text("المكتبة تجمع ملخصات قصص قرآنية ومواقف من السيرة والتاريخ ومواد تربوية قصيرة. بعض أخبار السيرة والتراجم تحتاج إلى مراجعة مصدرها ودرجة ثبوتها؛ لا تُعامل كل مادة على أنها حديث صحيح أو رواية قطعية. ارجع للقرآن والتفسير الموثوق، ولأهل العلم عند الحاجة.", modifier = Modifier.fillMaxWidth().padding(10.dp), fontSize = 10.sp, color = colors.onSurfaceVariant)
  }
}
